<template><ion-page><ion-content><main class="page-shell"><section class="form-card"><h1 class="page-title">Login</h1><p class="page-subtitle">Entre com seu e-mail e senha.</p><form @submit.prevent="submit"><ion-item class="field" lines="none"><ion-input v-model="email" label="E-mail" label-placement="stacked" type="email" autocomplete="email" required /></ion-item><ion-item class="field" lines="none"><div class="password-wrap"><ion-input v-model="password" label="Senha" label-placement="stacked" :type="showPassword ? 'text' : 'password'" autocomplete="current-password" required /><ion-button class="password-toggle" fill="clear" type="button" :aria-label="showPassword ? 'Ocultar senha' : 'Mostrar senha'" @click="showPassword = !showPassword"><ion-icon :icon="showPassword ? 'eye-off' : 'eye'" /></ion-button></div></ion-item><p v-if="error" class="notice error">{{ error }}</p><ion-button expand="block" type="submit" :disabled="loading">{{ loading ? 'Entrando…' : 'Entrar' }}</ion-button></form><div class="center"><router-link class="inline-link" to="/reset-password">Esqueci minha senha</router-link><br/><router-link class="inline-link" to="/register">Criar conta</router-link></div></section></main></ion-content></ion-page></template>
<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { IonButton, IonContent, IonIcon, IonInput, IonItem, IonPage } from '@ionic/vue'; import { login } from '../services/authService'; import { friendlyError } from '../utils/errors'
const router = useRouter(), email = ref(''), password = ref(''), showPassword = ref(false), loading = ref(false), error = ref('')
async function submit() { error.value = ''; if (!email.value.trim() || !password.value) { error.value = 'Preencha o e-mail e a senha.'; return } loading.value = true; try { await login(email.value, password.value); await router.replace('/welcome') } catch (e) { error.value = friendlyError(e) } finally { loading.value = false } }
</script>
